mapper.select:
SELECT id, cn_text AS cnText, language_code AS languageCode, original_translation AS originalTranslation, corrected_translation AS correctedTranslation, IFNULL(corrected_translation, original_translation) AS translation, is_corrected AS isCorrected, translation_source AS translationSource, create_time AS createTime, update_time AS updateTime FROM ${database.prefix.userms}hou_base_language_translation
AND cn_text LIKE CONCAT('%', #{param.keyword}, '%')
AND cn_text LIKE CONCAT('%', #{param.cnText}, '%')
AND language_code = #{param.languageCode}
AND is_corrected = #{param.isCorrected}
AND translation_source = #{param.translationSource}
ORDER BY update_time DESC
